"""Four wires: is the subgroup generated by some placed gates finite?

    python3 -B fin4.py

The orbit of e_0 under a finite group is finite; under an infinite one
the denominators of the coordinates grow.  Gates act on integer vectors
scaled by a power of two (exact)."""
import sys

N = 4
D = 1 << N


def bit(x, k):
    return x >> k & 1


def flip(t, cs=()):
    def f(v):
        s, w = v
        return s, tuple(w[j ^ (1 << t)] if all(bit(j, c) for c in cs) else w[j] for j in range(D))
    return f


def hh(a, b):
    def f(v):
        s, w = v
        out = []
        for i in range(D):
            acc = 0
            for j in range(D):
                if all(bit(i, k) == bit(j, k) for k in range(N) if k not in (a, b)):
                    sg = bit(i, a) * bit(j, a) + bit(i, b) * bit(j, b)
                    acc += -w[j] if sg % 2 else w[j]
            out.append(acc)
        return norm((s + 1, tuple(out)))
    return f


def swap(a, b):
    def f(v):
        s, w = v
        def g(j):
            return j ^ (1 << a) ^ (1 << b) if bit(j, a) != bit(j, b) else j
        return s, tuple(w[g(j)] for j in range(D))
    return f


def norm(v):
    s, w = v
    while s > 0 and all(x % 2 == 0 for x in w):
        s -= 1
        w = tuple(x // 2 for x in w)
    return s, w


GATES = {}
for i in range(N):
    GATES[f'X{i}'] = flip(i)
for a in range(N):
    for b in range(N):
        if a != b:
            GATES[f'CX{b}>{a}'] = flip(a, (b,))
for a in range(N):
    for b in range(a + 1, N):
        GATES[f'HH{a}{b}'] = hh(a, b)
        GATES[f'SW{a}{b}'] = swap(a, b)
for t in range(N):
    for c1 in range(N):
        for c2 in range(c1 + 1, N):
            if t not in (c1, c2):
                GATES[f'CCX{t};{c1}{c2}'] = flip(t, (c1, c2))


def wires(name):
    return {int(ch) for ch in name if ch.isdigit()}


def orbit(gens, cap=200000, smax=6):
    e0 = (0, tuple(1 if j == 0 else 0 for j in range(D)))
    seen = {e0}
    fr = [e0]
    while fr:
        new = []
        for v in fr:
            for g in gens:
                w = g(v)
                if w not in seen:
                    if w[0] > smax:
                        return None, len(seen)
                    seen.add(w)
                    new.append(w)
        fr = new
        if len(seen) > cap:
            return None, len(seen)
    return len(seen), max(v[0] for v in seen)


def on(ws):
    return [g for n, g in GATES.items() if wires(n) <= set(ws)]


if __name__ == '__main__':
    tests = {
        'G012': on([0, 1, 2]),
        'G012+G013': on([0, 1, 2]) + on([0, 1, 3]),
        'G012+HH03': on([0, 1, 2]) + [GATES['HH03']],
        'G012+X3+HH03': on([0, 1, 2]) + [GATES['HH03'], GATES['X3']],
        'CCX0;12,HH03,all2wire-on-012': [GATES['CCX0;12'], GATES['HH03']] + [g for n, g in GATES.items() if len(wires(n)) <= 2 and wires(n) <= {0, 1, 2}],
        'clifford4': [g for n, g in GATES.items() if not n.startswith('CCX')],
        'classical4': [g for n, g in GATES.items() if not n.startswith('HH')],
    }
    for k, gs in tests.items():
        print(k, orbit(gs), flush=True)
